<script lang="ts">
  import {parseDisarmPacket,submitDisarm,exportDisarm,readDisarm,type DisarmPacket} from './weapon-aware.ts';
  import {parseSwapPacket,submitSwap,exportSwap,readSwap,type SwapPacket} from './weapon-swap.ts';
  import {parseManagedEquipment,submitManagedEquipment,readArmedCompletion,exportArmedCompletion,type ManagedEquipmentProbe} from './managed-equipment.ts';
  let {connected,download,onbudget}:{connected:boolean;download:(name:string,value:unknown)=>void;onbudget:()=>void}=$props();
  let packet=$state<DisarmPacket|SwapPacket|ManagedEquipmentProbe>(),receipt=$state(readDisarm()),swap=$state(readSwap()),completion=$state(readArmedCompletion()),busy=$state(false),error=$state(''),fileInput:HTMLInputElement;
  const alreadySubmitted=$derived(packet?.kind==='managed-equipment-probe'?!!completion:packet?.kind==='weapon-aware-swap'?!!swap:!!receipt);
  async function imported(event:Event){try{const file=(event.target as HTMLInputElement).files?.[0];if(!file)return;const value=JSON.parse(await file.text());if(value.kind==='managed-equipment-probe'){if(value.request?.seed!==734)throw new Error('Use the reviewed missing-frame source packet in this panel.');packet=parseManagedEquipment(value);}else packet=value.kind==='weapon-aware-swap'?parseSwapPacket(value):parseDisarmPacket(value);error='';}catch(e){error=(e as Error).message;}}
  async function action(kind:'render'|'export-disarm'|'export-swap'|'export-completion'){if(busy)return;busy=true;error='';try{if(kind==='render'){if(!packet)throw new Error('Import the fixed test packet first.');if(packet.kind==='managed-equipment-probe')completion=await submitManagedEquipment(packet);else if(packet.kind==='weapon-aware-swap')swap=await submitSwap(packet);else receipt=await submitDisarm(packet);}else if(kind==='export-disarm')download('pixeldoll-weapon-aware-disarm.json',await exportDisarm());else if(kind==='export-swap')download('pixeldoll-weapon-aware-swap.json',await exportSwap());else download('pixeldoll-armed-completion.json',await exportArmedCompletion());}catch(e){error=(e as Error).message;}finally{receipt=readDisarm();swap=readSwap();completion=readArmedCompletion();onbudget();busy=false;}}
</script>
<details aria-label="Weapon-aware reverse experiment"><summary>Weapon-aware source and new frozen base</summary>
  <p>One separate disarm test on four existing armed green frames. Keep the visible source hand and remove the prop. Any revealed anatomy is a generated new base, not recovered skin. The earlier equipment failure remains recorded.</p>
  <p>The reviewed input removes two documented white specks. Exact reconstruction is tested against that derived target; raw provider images stay in the evidence.</p>
  <p>The reviewed disarm is eligible for one same-grip-family hatchet diagnostic. Twelve uncertain rim pixels still prevent claiming exact pure-weapon source reconstruction. The existing equipment gate remains failed.</p>
  <input hidden type="file" accept="application/json,.json" aria-label="Weapon-aware test packet" bind:this={fileInput} onchange={imported}/>
  <p>Missing east frames 0/2/5/7 use a separate armed-source request. A new body is frozen only after disarm; the original bare hand is not silently retained as aligned source metadata.</p>
  <div class="bu-actions"><button class="bu-btn" disabled={busy} onclick={()=>fileInput.click()}>Import weapon-aware test packet</button><button class="bu-btn" disabled={!connected||busy||!packet||alreadySubmitted} onclick={()=>action('render')}>Render selected weapon-aware test (reserve 25 gens)</button><button class="bu-btn" disabled={busy} onclick={()=>action('export-disarm')}>Export weapon-aware disarm evidence</button><button class="bu-btn" disabled={busy} onclick={()=>action('export-swap')}>Export weapon swap evidence</button><button class="bu-btn" disabled={busy} onclick={()=>action('export-completion')}>Export armed completion evidence</button></div>
  <p aria-live="polite">{busy?'Working on the selected weapon-aware action.':`Packet: ${packet?packet.kind+'; immutable source check runs before spending':'not loaded'}. Disarm: ${receipt?.jobId??'not submitted'}. Swap: ${swap?.jobId??'not submitted'}. Missing-frame source: ${completion?.jobId??'not submitted'}.`}</p>
  {#if error}<p class="bu-error" role="alert">{error}</p>{/if}
</details>
